// A testbench written against **real** UVM, for the corpus gate (U1-TEST-7).
//
// Deliberately minimal. Its job is not to exercise the extractor --- the stub
// fixtures do that far more cheaply --- but to check the one assumption the
// stub cannot check about itself: that real `uvm_component_registry`,
// `uvm_component`, and the real base-class chain behave the way the stub says
// they do.
//
// It also carries one `config_db` set/get pair and one virtual-interface
// binding, because real `uvm_config_db` is nothing like the stub's: it extends
// `uvm_resource_db#(T)` and its `set`/`get` delegate to a separate
// implementation class. The extraction keys on the *lexical* path of the called
// subroutine and on the specialization's `T` parameter, and neither of those
// assumptions can be checked against a stub that reproduces them by design.
//
// Compiled only when the UVM sources are present.

`include "uvm_macros.svh"

interface corpus_if;
  logic clk;
  modport mon_mp (input clk);
endinterface

// The RTL end of the bridge (U5).  Real `uvm_config_db#(T)::set` takes its
// value as a formal of type `T`, and whether slang still hands the extraction
// an interface *instance* through that formal --- rather than a conversion
// node with no symbol behind it --- is a question about the real library's
// signature, so it belongs here rather than in the stub.
module corpus_dut(corpus_if bus, input logic rst);
endmodule

module corpus_probe(corpus_if.mon_mp bus);
endmodule

package corpus_tb_pkg;
  import uvm_pkg::*;

  class corpus_item extends uvm_sequence_item;
    `uvm_object_utils(corpus_item)
    function new(string name = "corpus_item");
      super.new(name);
    endfunction
  endclass

  class corpus_driver extends uvm_driver #(corpus_item);
    `uvm_component_utils(corpus_driver)
    int n_items;
    function new(string name, uvm_component parent);
      super.new(name, parent);
    endfunction
    virtual function void build_phase(uvm_phase phase);
      super.build_phase(phase);
      // The idiom that matters: the `get` is an if-*condition*.
      if (!uvm_config_db #(int)::get(this, "", "n_items", n_items))
        n_items = 1;
    endfunction
  endclass

  class corpus_monitor extends uvm_monitor;
    `uvm_component_utils(corpus_monitor)
    uvm_analysis_port #(corpus_item) ap;
    function new(string name, uvm_component parent);
      super.new(name, parent);
    endfunction
    virtual function void build_phase(uvm_phase phase);
      super.build_phase(phase);
      ap = new("ap", this);
    endfunction
  endclass

  class corpus_sequencer extends uvm_sequencer #(corpus_item);
    `uvm_component_utils(corpus_sequencer)
    function new(string name, uvm_component parent);
      super.new(name, parent);
    endfunction
  endclass

  class corpus_agent extends uvm_agent;
    `uvm_component_utils(corpus_agent)
    corpus_driver    drv;
    corpus_monitor   mon;
    corpus_sequencer seqr;
    function new(string name, uvm_component parent);
      super.new(name, parent);
    endfunction
    virtual function void build_phase(uvm_phase phase);
      super.build_phase(phase);
      uvm_config_db #(int)::set(this, "drv", "n_items", 8);
      // Nothing reads this one: the orphan case, against the real library.
      uvm_config_db #(int)::set(this, "drv", "n_itmes", 4);
      drv  = corpus_driver::type_id::create("drv", this);
      mon  = corpus_monitor::type_id::create("mon", this);
      seqr = corpus_sequencer::type_id::create("seqr", this);
    endfunction
    virtual function void connect_phase(uvm_phase phase);
      super.connect_phase(phase);
      // Both ends are ports the *library* declares --- `seq_item_port` on
      // `uvm_driver`, `seq_item_export` on `uvm_sequencer_param_base`. Neither
      // exists in the stub, and the rule that hides unconnected library ports
      // must not hide these: they are connected, and they are the connection a
      // reader most wants to see.
      drv.seq_item_port.connect(seqr.seq_item_export);
    endfunction
  endclass

  // Real `uvm_scoreboard` and `uvm_subscriber` are what the tier taxonomy and
  // the port inventory are written against; the stub reproduces their *names*
  // and nothing else.  `uvm_analysis_imp` in particular is generated by a macro
  // in real UVM (`uvm_analysis_imp_decl` exists precisely because the plain one
  // is awkward), so whether a declared member of that type still reads as a
  // port is a question only this file can answer.
  class corpus_scoreboard extends uvm_scoreboard;
    `uvm_component_utils(corpus_scoreboard)
    uvm_analysis_imp #(corpus_item, corpus_scoreboard) aimp;
    function new(string name, uvm_component parent);
      super.new(name, parent);
    endfunction
    virtual function void build_phase(uvm_phase phase);
      super.build_phase(phase);
      aimp = new("aimp", this);
    endfunction
    virtual function void write(corpus_item t);
    endfunction
  endclass

  class corpus_env extends uvm_env;
    `uvm_component_utils(corpus_env)
    corpus_agent      agt;
    corpus_scoreboard sb;
    function new(string name, uvm_component parent);
      super.new(name, parent);
    endfunction
    virtual function void build_phase(uvm_phase phase);
      super.build_phase(phase);
      agt = corpus_agent::type_id::create("agt", this);
      sb  = corpus_scoreboard::type_id::create("sb", this);
    endfunction
    virtual function void connect_phase(uvm_phase phase);
      super.connect_phase(phase);
      // The §3.4 result, against the library it was probed on.  Real
      // `uvm_port_base #(IF) extends IF` --- a considerably deeper chain than
      // the stub's --- so both the `uvm_port_base::connect` discriminator and
      // the port-ness of each endpoint are being tested here, not assumed.
      agt.mon.ap.connect(sb.aimp);
    endfunction
  endclass

  // -- sequences -------------------------------------------------------------
  //
  // The one thing the stub genuinely cannot check about `` `uvm_do ``.  The
  // stub's `` `mini_do `` reproduces the *shape* of the macro --- several
  // statements for one line of source --- but real `uvm_do` is a different
  // animal: it declares a `uvm_sequence_base` local, branches on a `$cast` to
  // decide between `start_item`/`finish_item` and `start`, and wraps the
  // randomize call in an error check.  So the expansion contains a `start` on
  // a *library-typed* handle alongside the one that names the user's type, and
  // the rule that prefers the user-typed candidate is only exercised here.

  class corpus_sub_seq extends uvm_sequence #(corpus_item);
    `uvm_object_utils(corpus_sub_seq)
    function new(string name = "corpus_sub_seq");
      super.new(name);
    endfunction
    virtual task body();
      corpus_item it;
      `uvm_do(it)
    endtask
  endclass

  class corpus_seq extends uvm_sequence #(corpus_item);
    `uvm_object_utils(corpus_seq)
    bit do_sub = 1;
    function new(string name = "corpus_seq");
      super.new(name);
    endfunction
    virtual task body();
      corpus_sub_seq sub;
      `uvm_info("CORPUS", "starting", UVM_LOW)
      if (do_sub) begin
        sub = corpus_sub_seq::type_id::create("sub");
        sub.start(m_sequencer);
      end
      fork
        begin : traffic
          repeat (2) begin
            corpus_item it;
            `uvm_do(it)
          end
        end
        begin : timeout
          #100ns;
        end
      join_any
      disable fork;
    endtask
  endclass

  // -- factory overrides ------------------------------------------------------
  //
  // The stub reproduces the *signatures*, and the signatures are exactly what
  // this has to check: UVM's own argument orders disagree between the two inst
  // forms --- `uvm_component::set_inst_override_by_type` takes the path first,
  // `uvm_factory::set_inst_override_by_type` takes it last --- so a table of
  // argument positions written against the stub is a table of assumptions until
  // it is run against the library it describes.
  //
  // The registry form is the other question only real UVM answers: its
  // `set_type_override` delegates through `uvm_registry_common`, so whether the
  // specialization's `Tname` is still reachable from the called subroutine is a
  // fact about the real class hierarchy.

  class fast_corpus_driver extends corpus_driver;
    `uvm_component_utils(fast_corpus_driver)
    function new(string name, uvm_component parent);
      super.new(name, parent);
    endfunction
  endclass

  class noisy_corpus_monitor extends corpus_monitor;
    `uvm_component_utils(noisy_corpus_monitor)
    function new(string name, uvm_component parent);
      super.new(name, parent);
    endfunction
  endclass

  class corpus_test extends uvm_test;
    `uvm_component_utils(corpus_test)
    corpus_env env;
    virtual corpus_if vif;
    function new(string name, uvm_component parent);
      super.new(name, parent);
    endfunction
    virtual function void build_phase(uvm_phase phase);
      super.build_phase(phase);
      set_type_override_by_type(corpus_driver::get_type(),
                                fast_corpus_driver::get_type());
      set_inst_override_by_type("env.agt.drv",
                                corpus_driver::get_type(),
                                fast_corpus_driver::get_type());
      corpus_monitor::type_id::set_type_override(noisy_corpus_monitor::get_type());
      // The by-name form, with a typo. Compiles; silently never applies.
      set_type_override("corpus_scoreboard", "corpus_scorebaord");
      if (!uvm_config_db #(virtual corpus_if)::get(this, "", "vif", vif))
        `uvm_fatal("NOVIF", "no virtual interface")
      env = corpus_env::type_id::create("env", this);
    endfunction
  endclass

endpackage : corpus_tb_pkg

module corpus_tb_top;
  import uvm_pkg::*;
  import corpus_tb_pkg::*;

  logic rst;

  corpus_if u_if();

  corpus_dut   u_dut  (.bus(u_if), .rst(rst));
  corpus_probe u_probe(.bus(u_if.mon_mp));

  initial begin
    // The RTL bridge: set from a module, with a null cntxt.
    uvm_config_db #(virtual corpus_if)::set(null, "uvm_test_top", "vif", u_if);
    run_test("corpus_test");
  end
endmodule
